import copy, re

def sanitize_text(text):
    removed = []
    out = text
    for pat in DIRECTIVE_PATTERNS:
        for m in pat.finditer(out):
            removed.append(m.group(0).strip())
        out = pat.sub(" ", out)
    out = re.sub(r"[ \t]+", " ", out)
    out = re.sub(r"\n\s*\n+", "\n", out).strip()
    return SanitizedText(text=out, removed=removed)

def _walk(value, source, removed, key=None):
    if isinstance(value, dict):
        return {k: _walk(v, source, removed, k) for k, v in value.items()}
    if isinstance(value, list):
        return [_walk(v, source, removed) for v in value]
    if isinstance(value, str) and len(value) > 20:
        s = sanitize_text(value); removed.extend(s.removed)
        return wrap_as_data(source, s.text) if key in WRAP_KEYS else s.text
    return value
